export const columns=['employeeId','name','designation','basicPay','hra','da','conveyance','workingDays','overtimeHours','investment80C'];
export function calculate(e){const gross=e.basicPay+e.hra+e.da+e.conveyance;const pf=e.basicPay*.12;const professionalTax=200;const annualIncome=gross*12;const taxableIncome=Math.max(0,annualIncome-Math.min(e.investment80C,150000));const annualTax=taxableIncome<=300000?0:taxableIncome<=600000?(taxableIncome-300000)*.05:taxableIncome<=900000?15000+(taxableIncome-600000)*.1:45000+(taxableIncome-900000)*.15;const monthlyTDS=annualTax/12;return {gross,pf,professionalTax,annualIncome,taxableIncome,annualTax,monthlyTDS,net:gross-pf-professionalTax-monthlyTDS};}
export function validate(e){if(columns.slice(0,3).some(k=>typeof e[k]!=='string'||!e[k].trim()))return 'Employee ID, name, and designation are required.';if(columns.slice(3).some(k=>typeof e[k]!=='number'||!Number.isFinite(e[k])||e[k]<0||e[k]>1e12))return 'Amounts must be finite nonnegative numbers below 1 trillion.';if(!Number.isInteger(e.workingDays)||e.workingDays>31)return 'Working days must be a whole number from 0 to 31.';if(!Number.isInteger(e.overtimeHours))return 'Overtime hours must be a whole number.';return '';}
export function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw Error('CSV contains an unclosed quoted field.');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows[0]?.[0].replace(/^\uFEFF/,'').trim().toLowerCase()==='employeeid')rows.shift();return rows.map(row=>Object.fromEntries(columns.map((k,i)=>[k,i<3?(row[i]||'').trim():(row.length!==10||row[i]?.trim()===''?NaN:Number(row[i]))])));}
